/* Ironlog — helpers everything uses. Split out of index.html (r&d/notes/module-split.md). */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { S } from './app.js';
/* end imports */

/* ---------------- utils ---------------- */
export const $ = (s, r = document) => r.querySelector(s);
export const uid = () => Math.random().toString(36).slice(2, 10);
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
// RIR is what the lifter reports; RPE is what the internal effort math (e1rm,
// plausibility, historical data) already speaks. These two are one straight
// line — rir = 10 - rpe — so nothing about storage or calculation changes,
// only what's shown and typed at the edges.
export function rirToRpe(rir) { return rir == null || rir === '' ? null : 10 - rir; }
export function rpeToRir(rpe) { return rpe == null ? null : 10 - rpe; }

export function iso(d = new Date()) {
  const x = new Date(d);
  return `${x.getFullYear()}-${String(x.getMonth() + 1).padStart(2, '0')}-${String(x.getDate()).padStart(2, '0')}`;
}
export function parseISO(s) { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); }
export function today() { return iso(); }
export function daysBetween(a, b) { return Math.round((parseISO(b) - parseISO(a)) / 86400000); }
export function fmtDate(s, opt) {
  return parseISO(s).toLocaleDateString(undefined, opt || { weekday: 'short', month: 'short', day: 'numeric' });
}
export function relDay(s) {
  const d = daysBetween(today(), s);
  if (d === 0) return 'Today';
  if (d === 1) return 'Tomorrow';
  if (d === -1) return 'Yesterday';
  if (d < 0) return `${-d}d ago`;
  return `in ${d}d`;
}

// unit conversion
export const U = () => S.settings.units;
export const toKg = v => U() === 'kg' ? +v : +v / 2.2046226218;
export const fromKg = v => U() === 'kg' ? +v : +v * 2.2046226218;
export const inc = () => U() === 'kg' ? 2.5 : 5;
export function dw(kg, dec = 1) { // display weight (number)
  if (kg == null || isNaN(kg)) return 0;
  const v = fromKg(kg);
  return +(Math.round(v * 10 ** dec) / 10 ** dec);
}
export function w(kg, dec = 1) { return `${nice(dw(kg, dec))}<small>${U()}</small>`; }
export function wt(kg, dec = 1) { return `${nice(dw(kg, dec))}${U()}`; }
export function nice(n) { return (Math.round(n * 10) / 10).toString(); }
export function roundBar(kg) { // round to nearest loadable increment, in display units
  const step = inc();
  const disp = fromKg(kg);
  return toKg(Math.round(disp / step) * step);
}

// e1RM — Epley, capped at 12 reps for sanity
/* The reps left in the tank that e1RM counts. RPE 8 means two left, so the
   set is worth reps + 2. Past RIR 5 nobody's guess is reliable, so RIR 6 and
   up count as 5 (bug sweep 3.7) — before, they counted as 0, so 100 × 5 at
   RIR 6 was worth less than at RIR 5. No effort logged, or one outside the
   scale, counts as 0. */
export function e1Rir(rpe) {
  if (rpe == null || rpe === '' || !Number.isFinite(+rpe) || +rpe > 10) return 0;
  return +rpe < 5 ? 5 : 10 - rpe;
}
export function e1rm(kg, reps, rpe) {
  if (!kg || !reps) return 0;
  const rir = e1Rir(rpe);
  const eff = reps + rir;
  if (eff <= 1) return kg;
  return kg * (1 + Math.min(eff, 12) / 30);
}

// DOTS
export function dots(totalKg, bwKg, sex) {
  if (!totalKg || !bwKg) return 0;
  const c = sex === 'female'
    ? [-57.96288, 13.6175032, -0.1126655495, 0.0005158568, -0.0000010706]
    : [-307.75076, 24.0900756, -0.1918759221, 0.0007391293, -0.000001093];
  const x = clamp(bwKg, 40, 210);
  const denom = c[0] + c[1] * x + c[2] * x ** 2 + c[3] * x ** 3 + c[4] * x ** 4;
  if (denom <= 0) return 0;
  return totalKg * (500 / denom);
}

export function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
}

export function bodyweightKg() {
  const ci = [...S.checkins].filter(c => c.weight > 0).sort((a, b) => a.date < b.date ? 1 : -1)[0];
  return ci ? ci.weight : (S.settings.bodyweight || 0);
}
/* Where the number came from, so the profile can say so rather than showing a
   figure with no provenance — a stale fallback and a check-in from this morning
   look identical otherwise. */
export function bodyweightSource() {
  const ci = [...S.checkins].filter(c => c.weight > 0).sort((a, b) => a.date < b.date ? 1 : -1)[0];
  if (ci) return { kg: ci.weight, from: 'checkin', date: ci.date };
  if (S.settings.bodyweight) return { kg: S.settings.bodyweight, from: 'fallback' };
  return { kg: 0, from: 'none' };
}

/* ---------------- profile ----------------
   Age, and what the body data implies. Every field the profile stores is here
   because something reads it: sex and bodyweight set the DOTS coefficient, date
   of birth gives the masters category and a term in BMR, height and activity
   turn that into a maintenance calorie figure (kept for the Tools page, D11). */
export function ageFrom(dob) {
  if (!dob) return null;
  const d = parseISO(dob);
  if (!d || isNaN(d)) return null;
  const now = new Date();
  let a = now.getFullYear() - d.getFullYear();
  const m = now.getMonth() - d.getMonth();
  if (m < 0 || (m === 0 && now.getDate() < d.getDate())) a--;
  return a >= 0 && a < 120 ? a : null;
}

/* IPF divisions. Named for the federation because they are not universal —
   other federations draw the lines elsewhere. */
export function ageCategory(age) {
  if (age == null) return null;
  if (age < 14) return null;
  if (age <= 18) return 'Sub-junior';
  if (age <= 23) return 'Junior';
  if (age <= 39) return 'Open';
  if (age <= 49) return 'Masters 1';
  if (age <= 59) return 'Masters 2';
  if (age <= 69) return 'Masters 3';
  return 'Masters 4';
}

export const ACTIVITY = {
  sedentary: { mult: 1.2, label: 'Sedentary', note: 'desk job, no training' },
  light: { mult: 1.375, label: 'Light', note: 'training 1–3 days' },
  moderate: { mult: 1.55, label: 'Moderate', note: 'training 3–5 days' },
  high: { mult: 1.725, label: 'High', note: 'training 6–7 days' },
  athlete: { mult: 1.9, label: 'Very high', note: 'physical job plus training' },
};
export const NUTRITION_GOAL = {
  lose: { pct: -0.15, label: 'Lose' },
  maintain: { pct: 0, label: 'Maintain' },
  gain: { pct: 0.10, label: 'Gain' },
};

/* Mifflin-St Jeor — the usual estimate, and an estimate is all it is. One copy:
   the profile and the Tools TDEE calculator (D11) both come through here. */
export function bmrMifflin(kg, cm, age, sex) {
  if (!(kg > 0) || !(cm > 0) || !(age >= 0)) return 0;
  return Math.round(10 * kg + 6.25 * cm - 5 * age + (sex === 'female' ? -161 : 5));
}
function bmrKcal() {
  const age = ageFrom(S.settings.dob);
  return age == null ? 0 : bmrMifflin(bodyweightKg(), +S.settings.heightCm || 0, age, S.settings.sex);
}

/* Protein and fat are set per kilo of bodyweight and carbohydrate takes what is
   left, which is the way a lifter actually plans a day. Carbs floor at zero
   rather than going negative on a very low target. */
export function suggestedTargets() {
  const bmr = bmrKcal();
  if (!bmr) return null;
  const act = ACTIVITY[S.settings.activity] || ACTIVITY.moderate;
  const goal = NUTRITION_GOAL[S.settings.nutritionGoal] || NUTRITION_GOAL.maintain;
  const tdee = Math.round(bmr * act.mult);
  const kcal = Math.round((tdee * (1 + goal.pct)) / 10) * 10;
  const kg = bodyweightKg();
  const p = Math.round(kg * 2.0);
  const f = Math.round(kg * 0.8);
  const c = Math.max(0, Math.round((kcal - p * 4 - f * 9) / 4));
  return { bmr, tdee, kcal, p, c, f };
}

export const APP_VERSION = '0.96.5';

/* ---------------- sound, haptics, wake lock ----------------
   Shared by the hold timer and the rest timer, and meant for the cardio session
   on the roadmap too. No audio files: a Web Audio oscillator, so it works
   offline and weighs nothing. Mobile browsers refuse audio until a user
   gesture, so the context is only ever created by Cue.unlock(), which the tap
   that starts a timer calls — never on page load. */
export const Cue = {
  ctx: null,
  unlock() {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      if (!this.ctx || this.ctx.state === 'closed') this.ctx = new AC();
      if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
      return this.ctx;
    } catch (e) { return null; }
  },
  soundOn() { return S.settings.sound !== false; },
  vibeOn() { return S.settings.vibrate !== false; },
  /* One tone, `at` seconds from now on the audio clock. */
  beep(freq = 800, ms = 120, at = 0) {
    if (!this.soundOn()) return;
    const c = this.ctx;
    if (!c || c.state === 'closed') return;
    try {
      const t = c.currentTime + 0.03 + at, len = Math.max(60, ms) / 1000;
      const o = c.createOscillator(), g = c.createGain();
      o.type = 'sine';
      o.frequency.value = freq;
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.4, t + 0.012);
      g.gain.setValueAtTime(0.4, t + len - 0.04);
      g.gain.exponentialRampToValueAtTime(0.0001, t + len);
      o.connect(g);
      g.connect(c.destination);
      o.start(t);
      o.stop(t + len + 0.02);
    } catch (e) { /* a missed beep is not worth a crash */ }
  },
  buzz(pattern) {
    if (!this.vibeOn() || !navigator.vibrate) return;
    try { navigator.vibrate(pattern); } catch (e) { /* unsupported */ }
  },
  /* Two short, then one long that marks "go" — two seconds after the call. */
  countIn() {
    this.beep(800, 120, 0); this.beep(800, 120, 1); this.beep(1200, 450, 2);
    this.buzz(60);
    setTimeout(() => this.buzz(60), 1000);
    setTimeout(() => this.buzz(250), 2000);
  },
  tick() { this.beep(800, 90); },
  logged() { this.buzz(35); },   // a set ticked off: felt, not heard (C4)
  done() { this.beep(1200, 650); this.buzz([220, 120, 220]); },
};

/* Screen Wake Lock, shared by whoever needs the screen on. Refcounted by name so
   the rest timer releasing can't switch the screen off under a running hold.
   The browser drops the lock whenever the page is hidden, so it is taken again
   on return. Not available everywhere — failing is fine, the timers are
   timestamp-based and read correctly after the screen has slept. */
export const Awake = {
  who: new Set(), lock: null, pending: false,
  hold(name) { this.who.add(name); this._take(); },
  release(name) {
    this.who.delete(name);
    if (!this.who.size && this.lock) { const l = this.lock; this.lock = null; l.release().catch(() => {}); }
  },
  async _take() {
    if (this.lock || this.pending || !this.who.size) return;
    if (!('wakeLock' in navigator) || document.visibilityState !== 'visible') return;
    this.pending = true;
    try {
      const l = await navigator.wakeLock.request('screen');
      if (!this.who.size) l.release().catch(() => {});      // released while the request was in flight
      else { this.lock = l; l.addEventListener('release', () => { if (this.lock === l) this.lock = null; }); }
    } catch (e) { /* refused: low battery, no permission, unsupported */ }
    this.pending = false;
  },
};
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') Awake._take(); });
